<script setup>
import { computed,ref,watch,nextTick } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { useDemo } from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import FieldException from '../../components/FieldException.vue'
import StaticSection from '../../components/StaticSection.vue'
import {assessCase,caseRequirements,describeOperationalExceptions} from './reportRequirements.js'
import { printReport } from '../../lib/exports.js'
import { clone,incidentOptions,officeOptions,display } from './common.js'
const store=useDemo(),route=useRoute(),router=useRouter(),search=ref(''),status=ref(''),eventFilter=ref(route.query.eventId || ''),draft=ref(null),error=ref(''),success=ref('')
const actionTypes=['Show cause order','Notice / order','Decision','Penalty assessment','Penalty payment','Certificate suspension','Certificate lifting','SRB suspension','SRB lifting','Other']
const rows=computed(()=>store.visibleRecords('cases').filter(c=>(!eventFilter.value || c.eventId===eventFilter.value) && (!status.value || c.status===status.value) && `${c.caseNumber} ${c.party} ${c.violations}`.toLowerCase().includes((search.value || '').toLowerCase())))
const assessment=computed(()=>assessCase(draft.value||{}))
watch(assessment,value=>{for(const item of value.items)if(!item.missing)delete draft.value?.reportingExceptions?.[item.key]})
const required=key=>assessment.value.items.some(item=>item.key===key)
const fieldLabel=(label,key)=>label.replace(/\s*\*$/,'')+(required(key)?' *':'')
const actionKey=(action,index,key)=>`action:${action.id||`new-${index}`}:${key}`
function scrollToRequirement(item){const element=[...document.querySelectorAll('[data-requirement-key]')].find(element=>element.dataset.requirementKey===item?.key);element?.scrollIntoView({behavior:'smooth',block:'center'})}
const event=computed(()=>store.getEvent(draft.value?.eventId))
const columns=[{name:'caseNumber',label:'Case / incident',field:'caseNumber',align:'left',sortable:true},{name:'party',label:'Party / vessel',field:'party',align:'left',sortable:true},{name:'officeId',label:'Responsible office',field:'officeId',align:'left'},{name:'status',label:'Current outcome',field:'status',align:'left',sortable:true},{name:'penalty',label:'Penalty (PHP)',field:r=>r.penalty===null?'Unknown':r.penalty,align:'right'},{name:'actions',label:'',field:'id'}]
function load(){error.value='';success.value='';if(route.params.id){const record=store.visibleRecords('cases').find(c=>c.id===route.params.id);draft.value=record ? {...clone(record),reportingExceptions:clone(record.reportingExceptions||{})} : null}else if(route.query.new)create();else draft.value=null}
function create(){draft.value={eventId:eventFilter.value || route.query.eventId || '',caseNumber:'',vesselId:'',party:'',officeId:store.currentUser.value?.officeId || '',status:'ongoing_sco',violations:'',decision:'',decisionDate:'',penalty:null,paid:null,actions:[],reportingStatus:'draft',reportingExceptions:{}};error.value=''}
watch(()=>[route.params.id,route.query.new],load,{immediate:true})
watch(()=>store.visibleRecords('cases').map(c=>c.id).join('|'),()=>{if(route.params.id && !store.visibleRecords('cases').some(c=>c.id===route.params.id)){draft.value=null;error.value='This case is unavailable in your current account scope.'}})
function addAction(){draft.value.actions.push({id:`local-${Date.now()}-${draft.value.actions.length}`,type:'Show cause order',issuedDate:'',issuedTime:'',officeId:draft.value.officeId,reference:'',sourceTimeliness:'unknown',sourceRef:'',affectedDocument:'',relatedSuspension:'',surveyDetails:'',periodServed:'',conditionsMet:'',amount:null,conditions:'',notes:''})}
async function save(asDraft=false){try{error.value='';success.value='';if(!store.can('enforce',event.value))throw Error('Enforcement permission required.');if(!asDraft&&!assessment.value.ready){await nextTick();scrollToRequirement(assessment.value.unresolved[0]);throw Error(`${assessment.value.unresolved[0].label} is required. Enter it or explain an allowed Unknown / Not Applicable beside the field (${assessment.value.unresolved.length} item(s) remaining).`)}const data=clone(draft.value);data.reportingStatus=asDraft?'draft':'recorded';for(const key of ['penalty','paid']){data[key]=data[key]==='' || data[key]===null || data[key]===undefined ? null : Number(data[key]);if(data[key]!==null && (!Number.isFinite(data[key]) || data[key]<0))throw Error('Penalty and paid amounts must be non-negative or unknown.')}for(const action of data.actions||[])if(/penalty/i.test(action.type||'')){action.amount=action.amount===''||action.amount==null?null:Number(action.amount);if(action.amount!==null&&(!Number.isFinite(action.amount)||action.amount<0))throw Error('Action amounts must be non-negative or unknown.')}data.updatedAt=new Date().toISOString();data.createdAt ||=data.updatedAt;data.history ||= [];data.history.push({at:data.updatedAt,actorId:store.currentUser.value?.id,actorName:store.currentUser.value?.name,status:data.status,remarks:`Case saved; ${data.actions.length} recorded actions`});const result=data.id ? store.update('cases',data.id,data) : store.recordCase(data);draft.value=clone(result);success.value=asDraft?'Case draft saved.':'Case and action history saved.';if(!route.params.id)router.replace(`/admin/cases/${result.id}`)}catch(e){error.value=e.message}}
function preview(){const c=draft.value;printReport({title:`Enforcement case ${c.caseNumber}`,subtitle:'Demonstration / fictional data',metadata:{incident:event.value?.ref,office:c.officeId,status:c.status},sections:[{title:'Case particulars',content:`Party: ${display(c.party)}\nViolations: ${display(c.violations)}\nDecision: ${display(c.decision)}\nDecision date: ${display(c.decisionDate)}\nPenalty PHP: ${display(c.penalty)}\nPaid PHP: ${display(c.paid)}`},{title:'Orders and certificate / SRB actions',content:(c.actions||[]).map((a,i)=>`${i+1}. ${a.type} · ${display(a.reference)}\nIssued ${display(a.issuedDate)} ${a.issuedTime || 'Time unknown'} · ${display(a.officeId)}\nSource timeliness: ${display(a.sourceTimeliness)}\nConditions: ${display(a.conditions)}\nSource reference: ${display(a.sourceRef)}\nAffected document / person: ${display(a.affectedDocument)}\nRelated suspension: ${display(a.relatedSuspension)}\nSurvey warranting lifting: ${display(a.surveyDetails)}\nSRB period served: ${display(a.periodServed)}\nSRB compliance for lifting: ${display(a.conditionsMet)}\nAction amount PHP: ${display(a.amount)}\n${a.notes || ''}`).join('\n\n')},{title:'Case / Action Reporting Exceptions',content:describeOperationalExceptions(c,caseRequirements(c))}]})}
</script>
<template><div class="page-wrap"><PageHeader :title="draft ? (draft.caseNumber || 'New enforcement case') : 'Enforcement case register'" subtitle="Keep case outcomes, orders and certificate / SRB actions distinct from incident review."><template #actions><q-btn v-if="draft" outline no-caps label="Case register" to="/admin/cases" @click="draft=null"/><q-btn v-if="!draft" color="primary" no-caps icon="add" label="New case" @click="create"/><q-btn v-if="draft" outline no-caps icon="print" label="Preview case" @click="preview"/></template></PageHeader><q-banner v-if="error" class="bg-red-1 text-negative q-mb-md" rounded>{{error}}</q-banner><q-banner v-if="success" class="bg-green-1 text-positive q-mb-md" rounded>{{success}}</q-banner>
<template v-if="!draft && !route.params.id"><div class="panel toolbar-row q-mb-md"><q-input v-model="search" outlined dense clearable label="Search case, party or violation"/><q-select v-model="status" :options="[{label:'Ongoing SCO',value:'ongoing_sco'},{label:'Ongoing Penalty',value:'ongoing_penalty'},{label:'Dismissed',value:'dismissed'},{label:'Closed',value:'closed'}]" emit-value map-options outlined dense clearable label="Case outcome" style="min-width:190px"/><q-select v-model="eventFilter" outlined dense clearable :options="incidentOptions(store.visibleEvents.value)" emit-value map-options label="Related incident" style="min-width:260px"/><q-space/><span class="muted">{{rows.length}} cases</span></div><div class="panel"><q-table flat :rows="rows" :columns="columns" row-key="id" :pagination="{rowsPerPage:10}"><template #body-cell-caseNumber="p"><q-td :props="p"><router-link class="record-link" :to="`/admin/cases/${p.row.id}`">{{p.row.caseNumber}}</router-link><div class="muted">{{store.getEvent(p.row.eventId)?.ref}}</div></q-td></template><template #body-cell-party="p"><q-td :props="p">{{p.row.party || 'Party unknown'}}<div class="muted">{{store.getEvent(p.row.eventId)?.vessels.find(v=>v.id===p.row.vesselId)?.name || 'Vessel not linked'}}</div></q-td></template><template #body-cell-status="p"><q-td :props="p"><StatusBadge :status="p.row.status"/></q-td></template><template #body-cell-actions="p"><q-td :props="p"><q-btn flat color="primary" no-caps label="Open case" :to="`/admin/cases/${p.row.id}`"/></q-td></template></q-table></div></template>
<q-form v-else-if="draft" @submit="save(false)"><div class="panel"><div class="section-title" id="case-header">Case particulars and outcome<q-chip v-if="draft.reportingStatus==='draft'" size="sm">Draft</q-chip></div><div class="form-grid"><section :data-requirement-key="'caseNumber'"><q-input v-model="draft.caseNumber" outlined :label="fieldLabel('Case number *','caseNumber')"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="'caseNumber'"/></section><section :data-requirement-key="'eventId'"><q-select v-model="draft.eventId" @update:model-value="draft.vesselId=''" outlined :options="incidentOptions(store.visibleEvents.value)" emit-value map-options :label="fieldLabel('Related incident *','eventId')"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="'eventId'"/></section><section :data-requirement-key="'vesselId'"><q-select v-model="draft.vesselId" outlined clearable :options="(event?.vessels || []).map(v=>({label:v.name,value:v.id}))" emit-value map-options :label="fieldLabel('Involved vessel','vesselId')"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="'vesselId'"/></section><section :data-requirement-key="'party'"><q-input v-model="draft.party" outlined :label="fieldLabel('Respondent / owner / operator *','party')"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="'party'"/></section><section :data-requirement-key="'officeId'"><q-select v-model="draft.officeId" outlined :options="officeOptions(store)" emit-value map-options :label="fieldLabel('Responsible office *','officeId')"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="'officeId'"/></section><section :data-requirement-key="'status'"><q-select v-model="draft.status" outlined :options="[{label:'Ongoing SCO',value:'ongoing_sco'},{label:'Ongoing Penalty',value:'ongoing_penalty'},{label:'Dismissed',value:'dismissed'},{label:'Closed',value:'closed'}]" emit-value map-options :label="fieldLabel('Current case outcome *','status')"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="'status'"/></section><section class="span-2" :data-requirement-key="'violations'"><q-input v-model="draft.violations" outlined type="textarea" :label="fieldLabel('Alleged violations and relevant provisions','violations')"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="'violations'"/></section><section class="span-2" :data-requirement-key="'decision'"><q-input v-model="draft.decision" outlined type="textarea" :label="fieldLabel('Decision / disposition and rationale','decision')"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="'decision'"/></section><section :data-requirement-key="'decisionReference'"><q-input v-model="draft.decisionReference" outlined :label="fieldLabel('Decision / Order Reference *','decisionReference')"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="'decisionReference'"/></section><section :data-requirement-key="'decisionDate'"><q-input v-model="draft.decisionDate" outlined type="date" stack-label :label="fieldLabel('Decision date (blank if unknown)','decisionDate')"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="'decisionDate'"/></section><section :data-requirement-key="'penalty'"><q-input v-model="draft.penalty" outlined type="number" min="0" step="0.01" :label="fieldLabel('Assessed penalty PHP (blank = unknown)','penalty')"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="'penalty'"/></section><section :data-requirement-key="'paid'"><q-input v-model="draft.paid" outlined type="number" min="0" step="0.01" :label="fieldLabel('Paid amount PHP (blank = unknown)','paid')"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="'paid'"/></section></div></div>
<div class="panel q-mt-md"><div class="toolbar-row"><div><div class="section-title">Orders and actions</div><p class="muted q-mb-none">Add each SCO, order, decision, payment, suspension and lifting separately.</p></div><q-space/><q-btn outline no-caps icon="add" label="Add action" @click="addAction"/></div><section class="q-mt-md" data-requirement-key="scoRecord"><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" field-key="scoRecord"/></section><q-banner class="q-my-md bg-blue-1 text-primary" rounded>Within / beyond 72H is a source-recorded category. No legal timing rule is inferred. Unknown occurrence or issue timestamps remain unknown.</q-banner><StaticSection v-for="(a,i) in draft.actions" :key="a.id" :id="`case-action:${a.id}`" :label="`${i+1}. ${a.type} · ${a.reference || 'Reference pending'}`" class="q-mb-md"><div class="form-grid q-pa-sm"><section :data-requirement-key="actionKey(a,i,'type')"><q-select v-model="a.type" outlined :options="actionTypes" :label="fieldLabel('Action type *',actionKey(a,i,'type'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'type')"/></section><section :data-requirement-key="actionKey(a,i,'reference')"><q-input v-model="a.reference" outlined :label="fieldLabel('Order / certificate / SRB reference *',actionKey(a,i,'reference'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'reference')"/></section><section :data-requirement-key="actionKey(a,i,'issuedDate')"><q-input v-model="a.issuedDate" outlined type="date" stack-label :label="fieldLabel('Issue date (blank = unknown) *',actionKey(a,i,'issuedDate'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'issuedDate')"/></section><section :data-requirement-key="actionKey(a,i,'issuedTime')"><q-input v-model="a.issuedTime" outlined type="time" stack-label :label="fieldLabel('Issue time (blank = unknown) *',actionKey(a,i,'issuedTime'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'issuedTime')"/></section><section :data-requirement-key="actionKey(a,i,'officeId')"><q-select v-model="a.officeId" outlined :options="officeOptions(store)" emit-value map-options :label="fieldLabel('Actual issuing office *',actionKey(a,i,'officeId'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'officeId')"/></section><section :data-requirement-key="actionKey(a,i,'sourceTimeliness')"><q-select v-model="a.sourceTimeliness" outlined :options="[{label:'Unknown / not stated',value:'unknown'},{label:'Within 72H — recorded in source',value:'within_72h_source'},{label:'Beyond 72H — recorded in source',value:'beyond_72h_source'},{label:'Not applicable',value:'not_applicable'}]" emit-value map-options :label="fieldLabel('Source timeliness category *',actionKey(a,i,'sourceTimeliness'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'sourceTimeliness')"/></section><section :data-requirement-key="actionKey(a,i,'sourceRef')"><q-input v-model="a.sourceRef" outlined :label="fieldLabel('Source Document / Copy Reference *',actionKey(a,i,'sourceRef'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'sourceRef')"/></section>
 <template v-if="/certificate|srb/i.test(a.type)"><section :data-requirement-key="actionKey(a,i,'affectedDocument')"><q-input v-model="a.affectedDocument" outlined :label="fieldLabel('Affected Certificate / SRB / Person *',actionKey(a,i,'affectedDocument'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'affectedDocument')"/></section><section v-if="/lifting/i.test(a.type)" :data-requirement-key="actionKey(a,i,'relatedSuspension')"><q-input v-model="a.relatedSuspension" outlined :label="fieldLabel('Related Suspension Reference *',actionKey(a,i,'relatedSuspension'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'relatedSuspension')"/></section><section v-if="/certificate/i.test(a.type)&&/lifting/i.test(a.type)" class="span-2" :data-requirement-key="actionKey(a,i,'surveyDetails')"><q-input v-model="a.surveyDetails" outlined type="textarea" :label="fieldLabel('Survey Warranting Certificate Lifting *',actionKey(a,i,'surveyDetails'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'surveyDetails')"/></section><template v-if="/srb/i.test(a.type)&&/lifting/i.test(a.type)"><section :data-requirement-key="actionKey(a,i,'periodServed')"><q-input v-model="a.periodServed" outlined :label="fieldLabel('Period Lapsed / Served *',actionKey(a,i,'periodServed'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'periodServed')"/></section><section class="span-2" :data-requirement-key="actionKey(a,i,'conditionsMet')"><q-input v-model="a.conditionsMet" outlined type="textarea" :label="fieldLabel('Compliance Warranting SRB Lifting *',actionKey(a,i,'conditionsMet'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'conditionsMet')"/></section></template></template><section v-if="/penalty/i.test(a.type)" :data-requirement-key="actionKey(a,i,'amount')"><q-input v-model="a.amount" outlined type="number" min="0" step="0.01" :label="fieldLabel('Action Amount (PHP) *',actionKey(a,i,'amount'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'amount')"/></section>
 <section class="span-2" :data-requirement-key="actionKey(a,i,'conditions')"><q-input v-model="a.conditions" outlined type="textarea" :label="fieldLabel('Conditions, affected document / person and lifting requirements',actionKey(a,i,'conditions'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'conditions')"/></section><section class="span-2" :data-requirement-key="actionKey(a,i,'notes')"><q-input v-model="a.notes" outlined type="textarea" :label="fieldLabel('Evidence / source reference and action remarks',actionKey(a,i,'notes'))"/><FieldException :assessment="assessment" :exceptions="draft.reportingExceptions" :field-key="actionKey(a,i,'notes')"/></section><q-btn flat color="negative" no-caps label="Remove unsaved action entry" @click="draft.actions.splice(i,1)"/></div></StaticSection><p v-if="!draft.actions.length" class="muted">No enforcement actions recorded. Add the first SCO or other action.</p></div><div class="panel q-mt-md" v-if="draft.history?.length"><div class="section-title">Case history</div><p v-for="(h,i) in [...draft.history].reverse()" :key="i" class="muted">{{h.at ? new Date(h.at).toLocaleString() : 'Time unknown'}} · {{h.actorName || h.actorId}} · {{h.status}} · {{h.remarks}}</p></div><div class="toolbar-row q-mt-md"><q-btn outline no-caps color="primary" label="Save draft" @click="save(true)"/><q-btn color="primary" no-caps icon="save" label="Save case and actions" type="submit"/><q-btn flat no-caps label="Open incident" :to="`/admin/incidents/${draft.eventId}`" :disable="!draft.eventId"/></div></q-form>
<section v-else class="panel"><h2>Case unavailable</h2><p>This case was not found or is unavailable to your account.</p><q-btn to="/admin/cases" color="primary" no-caps label="Case register"/></section></div></template>
<style scoped>.form-grid>section{min-width:0}</style>
